Replace `index.ts` with the following. The bucket URL is derived with `apply`, and the database password remains a secret `Output<string>` from Pulumi configuration.

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();

const env = config.get("env") ?? pulumi.getStack();
const region = config.get("region") ?? "us-east-1";
const dbPassword = config.requireSecret("dbPassword");

const isProd = env === "prod";

// S3 bucket
const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: {
        enabled: true,
    },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
    tags: {
        Environment: env,
        Project: "myapp",
    },
});

new aws.s3.BucketPublicAccessBlock("app-bucket-public-access-block", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// Output values must be transformed with apply(), not await.
const bucketUrl = bucket.bucketRegionalDomainName.apply(
    domainName => `https://${domainName}`,
);

// RDS instance
const db = new aws.rds.Instance("app-db", {
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app_user",
    password: dbPassword,

    multiAz: isProd,
    storageEncrypted: isProd,
    publiclyAccessible: false,
    backupRetentionPeriod: 7,
    deletionProtection: true,

    // Deletion protection prevents accidental deletion. If intentionally
    // destroying the DB, disable it first and retain a final snapshot.
    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `myapp-${env}-final-snapshot`,

    tags: {
        Environment: env,
        Project: "myapp",
    },
});

export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

Configure each stack independently, storing the password as an encrypted Pulumi config secret:

```bash
pulumi stack init dev
pulumi config set env dev
pulumi config set region us-east-1
pulumi config set --secret dbPassword '...'

pulumi stack init prod
pulumi config set env prod
pulumi config set region us-east-1
pulumi config set --secret dbPassword '...'
```

This produces separate `Pulumi.dev.yaml` and `Pulumi.prod.yaml` files. The encrypted `secure:` value may be committed, but plaintext passwords must not be committed. Also set the AWS provider region through the normal Pulumi AWS configuration if it is not already configured:

```bash
pulumi config set aws:region us-east-1
```
